LAB('vault-consul-lab-18', 'Recover a Deleted Secret with kv-v2',
 'Use kv-v2 versioning to soft-delete, recover, and permanently destroy a secret.',
 ['Write v1: run `vault kv put secret/lab-app/db password=one`.',
  'Write v2: run `vault kv put secret/lab-app/db password=two` and confirm version 2.',
  'Soft-delete: run `vault kv delete secret/lab-app/db` \u2014 reads now fail, but data is recoverable.',
  'Undelete: run `vault kv undelete -versions=2 secret/lab-app/db` and read it back.',
  'Destroy version 1 permanently: run `vault kv destroy -versions=1 secret/lab-app/db`.',
  'Confirm: version 2 readable, version 1 gone forever \u2014 delete vs destroy, demonstrated.'],
 [CK('vault kv put secret/lab-app/db', 'lab-app', 'Write with `vault kv put secret/lab-app/db password=one`.'),
  CK('vault kv delete secret/lab-app/db', 'delete', 'Soft-delete with `vault kv delete secret/lab-app/db`.'),
  CK('vault kv undelete', 'undelete', 'Recover with `vault kv undelete -versions=2 secret/lab-app/db`.')],
 'Versioning mastered \u2014 soft-delete recovers, destroy is forever.'),

